package com.careerpilot.modules.dsa.service;

import com.careerpilot.exception.NotFoundException;
import com.careerpilot.modules.auth.entity.User;
import com.careerpilot.modules.dsa.dto.DsaDtos.*;
import com.careerpilot.modules.dsa.entity.*;
import com.careerpilot.modules.dsa.repository.DsaTopicProgressRepository;
import com.careerpilot.modules.dsa.taxonomy.DsaTopicTaxonomy;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.Instant;
import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;

@Service public class DsaPracticeService {
 public static final String FORMULA_VERSION="dsa-readiness-v1";
 public static final String STRIVER_URL="https://takeuforward.org/strivers-a2z-dsa-course/strivers-a2z-dsa-course-sheet-2/";
 private final DsaTopicProgressRepository repository;private final DsaTopicTaxonomy taxonomy;
 public DsaPracticeService(DsaTopicProgressRepository repository,DsaTopicTaxonomy taxonomy){this.repository=repository;this.taxonomy=taxonomy;}
 @Transactional(readOnly=true)public Dashboard dashboard(User user){return build(repository.findByUserIdOrderByUpdatedAtDesc(user.getId()));}
 @Transactional public Dashboard update(User user,String topicId,UpdateProgressRequest request){var topic=taxonomy.find(topicId).orElseThrow(()->new NotFoundException("DSA topic not found"));var progress=repository.findByUserIdAndTopicId(user.getId(),topic.id()).orElseGet(()->{var value=new DsaTopicProgress();value.setUser(user);value.setTopicId(topic.id());return value;});var now=Instant.now();progress.setStatus(request.status());progress.setSelfConfidence(request.selfConfidence());if(request.status()!=DsaProgressStatus.NOT_STARTED){progress.setAttemptCount(progress.getAttemptCount()+1);progress.setLastPracticedAt(now);}if(request.status()==DsaProgressStatus.SOLVED&&progress.getSolvedAt()==null)progress.setSolvedAt(now);repository.save(progress);return build(repository.findByUserIdOrderByUpdatedAtDesc(user.getId()));}
 public Dashboard build(List<DsaTopicProgress>rows){var byId=rows.stream().collect(Collectors.toMap(DsaTopicProgress::getTopicId,Function.identity(),(a,b)->a));var topics=taxonomy.all().stream().map(topic->map(topic,byId.get(topic.id()))).toList();int solved=(int)topics.stream().filter(v->v.status()==DsaProgressStatus.SOLVED).count(),attempted=(int)topics.stream().filter(v->v.status()==DsaProgressStatus.ATTEMPTED).count(),revise=(int)topics.stream().filter(v->v.status()==DsaProgressStatus.REVISE).count(),tracked=(int)topics.stream().filter(v->v.status()!=DsaProgressStatus.NOT_STARTED).count();int progress=(int)Math.round(100.0*solved/topics.size());var next=topics.stream().filter(TopicProgress::enoughEvidence).filter(v->v.status()!=DsaProgressStatus.SOLVED).min(Comparator.comparingInt((TopicProgress v)->v.readinessScore()==null?101:v.readinessScore()).thenComparingInt(v->taxonomy.find(v.topicId()).orElseThrow().order())).orElseGet(()->topics.stream().filter(v->v.status()==DsaProgressStatus.NOT_STARTED).findFirst().orElse(null));return new Dashboard(new Summary(progress,solved,attempted,revise,tracked,next==null?null:next.topicId(),next==null?null:next.topicName(),FORMULA_VERSION),topics,"DSA topic readiness is an explainable application heuristic based on your recorded practice activity. It is not a standardized coding ability score.",STRIVER_URL,"Striver's A2Z DSA Sheet is an external learning resource and is not owned by Career Guidance AI.");}
 private TopicProgress map(DsaTopicTaxonomy.Topic topic,DsaTopicProgress row){if(row==null)return new TopicProgress(topic.id(),topic.name(),DsaProgressStatus.NOT_STARTED,0,null,null,null,null,"Not enough practice data",false);boolean enough=row.getStatus()==DsaProgressStatus.SOLVED||row.getAttemptCount()>=2;if(!enough)return new TopicProgress(topic.id(),topic.name(),row.getStatus(),row.getAttemptCount(),row.getSelfConfidence(),row.getLastPracticedAt(),row.getSolvedAt(),null,"Not enough practice data",false);int base=switch(row.getStatus()){case SOLVED->85;case REVISE->45;case ATTEMPTED->35;case NOT_STARTED->0;};int confidence=row.getSelfConfidence()==null?0:(row.getSelfConfidence()-3)*5;int practice=Math.min(10,Math.max(0,row.getAttemptCount()-2)*2);int score=Math.max(0,Math.min(100,base+confidence+practice));String label=score>=75?"Strong":score>=50?"Developing":score>=25?"Needs Practice":"Priority";return new TopicProgress(topic.id(),topic.name(),row.getStatus(),row.getAttemptCount(),row.getSelfConfidence(),row.getLastPracticedAt(),row.getSolvedAt(),score,label,true);}
 public Map<String,String>copilotEvidence(User user){var d=dashboard(user);var practiced=d.topics().stream().filter(TopicProgress::enoughEvidence).toList();var result=new LinkedHashMap<String,String>();result.put("Overall DSA progress",d.summary().overallProgress()+"% solved taxonomy topics");result.put("DSA revision due",String.valueOf(d.summary().revisionDue()));result.put("Recommended DSA topic",d.summary().recommendedTopicName()==null?"Unavailable":d.summary().recommendedTopicName());practiced.stream().max(Comparator.comparingInt(TopicProgress::readinessScore)).ifPresent(v->result.put("Strongest practiced DSA topic",v.topicName()+" ("+v.readinessScore()+"/100, "+v.readinessLabel()+")"));practiced.stream().min(Comparator.comparingInt(TopicProgress::readinessScore)).ifPresent(v->result.put("Priority practiced DSA topic",v.topicName()+" ("+v.readinessScore()+"/100, "+v.readinessLabel()+")"));return result;}
}
